namespace sv_0bcdb6b82efa4c26979c3bc3a2e5ae42.Services;

public enum ThemeMode
{
    Light,
    Dark,
    System
}

/// <summary>
/// Scoped service — one instance per circuit.
/// All interactive-server components in the same browser tab share this instance.
/// </summary>
public sealed class ThemeService
{
    private ThemeMode _theme = ThemeMode.System;
    private string _accentColor = "#0d6efd"; // Bootstrap primary

    public ThemeMode Theme
    {
        get => _theme;
        set
        {
            if (_theme == value) return;
            _theme = value;
            NotifyChanged();
        }
    }

    public string AccentColor
    {
        get => _accentColor;
        set
        {
            if (_accentColor == value) return;
            _accentColor = value;
            NotifyChanged();
        }
    }

    /// <summary>
    /// Fired whenever Theme or AccentColor changes.
    /// Subscribers call StateHasChanged() in their handler.
    /// </summary>
    public event Action? OnChanged;

    /// <summary>
    /// Bulk-update both values with a single notification.
    /// </summary>
    public void Update(ThemeMode theme, string accentColor)
    {
        bool changed = _theme != theme || _accentColor != accentColor;
        _theme = theme;
        _accentColor = accentColor;
        if (changed) NotifyChanged();
    }

    private void NotifyChanged() => OnChanged?.Invoke();
}

@* Interactive island — lives in the static layout but runs on the shared circuit *@
@rendermode InteractiveServer
@implements IDisposable
@inject ThemeService ThemeService

<span class="theme-indicator" title="Current theme">
    @switch (ThemeService.Theme)
    {
        case ThemeMode.Light:
            <span>☀️ Light</span>
            break;
        case ThemeMode.Dark:
            <span>🌙 Dark</span>
            break;
        case ThemeMode.System:
            <span>💻 System</span>
            break;
    }
    <span class="accent-dot" style="background-color: @ThemeService.AccentColor;"></span>
</span>

@code {
    protected override void OnInitialized()
    {
        ThemeService.OnChanged += HandleThemeChanged;
    }

    private void HandleThemeChanged()
    {
        InvokeAsync(StateHasChanged);
    }

    public void Dispose()
    {
        ThemeService.OnChanged -= HandleThemeChanged;
    }
}

@* Reusable toggle — can be dropped into any interactive page or island *@
@implements IDisposable
@inject ThemeService ThemeService

<div class="theme-toggle">
    <label>Theme:</label>
    <select class="form-select form-select-sm d-inline-block w-auto ms-1"
            value="@ThemeService.Theme"
            @onchange="OnThemeSelected">
        @foreach (var mode in Enum.GetValues<ThemeMode>())
        {
            <option value="@mode">@mode</option>
        }
    </select>
</div>

@code {
    protected override void OnInitialized()
    {
        ThemeService.OnChanged += HandleThemeChanged;
    }

    private void OnThemeSelected(ChangeEventArgs e)
    {
        if (Enum.TryParse<ThemeMode>(e.Value?.ToString(), out var mode))
        {
            ThemeService.Theme = mode;
        }
    }

    private void HandleThemeChanged()
    {
        InvokeAsync(StateHasChanged);
    }

    public void Dispose()
    {
        ThemeService.OnChanged -= HandleThemeChanged;
    }
}

@page "/settings"
@rendermode InteractiveServer
@implements IDisposable
@inject ThemeService ThemeService

<PageTitle>Settings</PageTitle>

<h1>User Preferences</h1>

<div class="card mt-3" style="max-width: 480px;">
    <div class="card-body">
        <h5 class="card-title">Theme</h5>

        <div class="mb-3">
            <label class="form-label">Mode</label>
            <select class="form-select" value="@_selectedTheme"
                    @onchange="OnThemeChanged">
                @foreach (var mode in Enum.GetValues<ThemeMode>())
                {
                    <option value="@mode">@mode</option>
                }
            </select>
        </div>

        <div class="mb-3">
            <label class="form-label">Accent Color</label>
            <input type="color" class="form-control form-control-color"
                   value="@_selectedAccent"
                   @onchange="OnAccentChanged" />
        </div>

        <button class="btn btn-primary" @onclick="Save">Save Preferences</button>

        <p class="text-muted mt-2 mb-0">
            Current: <strong>@ThemeService.Theme</strong> /
            <span style="color: @ThemeService.AccentColor;">■</span>
            @ThemeService.AccentColor
        </p>
    </div>
</div>

@code {
    private ThemeMode _selectedTheme;
    private string _selectedAccent = string.Empty;

    protected override void OnInitialized()
    {
        _selectedTheme = ThemeService.Theme;
        _selectedAccent = ThemeService.AccentColor;
        ThemeService.OnChanged += HandleThemeChanged;
    }

    private void OnThemeChanged(ChangeEventArgs e)
    {
        if (Enum.TryParse<ThemeMode>(e.Value?.ToString(), out var mode))
            _selectedTheme = mode;
    }

    private void OnAccentChanged(ChangeEventArgs e)
    {
        _selectedAccent = e.Value?.ToString() ?? _selectedAccent;
    }

    private void Save()
    {
        // Single notification for both changes
        ThemeService.Update(_selectedTheme, _selectedAccent);
    }

    private void HandleThemeChanged()
    {
        _selectedTheme = ThemeService.Theme;
        _selectedAccent = ThemeService.AccentColor;
        InvokeAsync(StateHasChanged);
    }

    public void Dispose()
    {
        ThemeService.OnChanged -= HandleThemeChanged;
    }
}

